/** Cap Free Wizard to the curated allowlist (shared across demographics). */
{
  const allow = new Set<string>(FREE_WIZARD_HUSTLE_IDS);
  for (const h of SIDE_HUSTLES) {
    h.freeWizardEligible = allow.has(h.id);
  }
}

/**
 * AI hustles default to Elite. Small exceptions can be Free or Starter.
 */
/** Reserved — no Free AI hustles right now. */
export const AI_SIDE_HUSTLE_FREE_IDS = [] as const;

/** Reserved — coffee-chat teaching moved to Elite with the COMPLETE #028 spec. */
export const AI_SIDE_HUSTLE_STARTER_IDS = [] as const;

/** Reserved — simpler AI helpers moved to Elite with Digital/AI policy. */
export const AI_SIDE_HUSTLE_PRO_IDS = [] as const;

export const AI_SIDE_HUSTLE_ELITE_IDS = [
  "ai-assets",
  "ai-timing",
  "ai-agents",
  "ai-promo-video",
  "ai-peers",
  "create-games-kids",
  "create-games-junior",
  "ai-social-helper",
  "ai-prompt-helper",
  "local-business-ai-setup",
] as const;

export function isAiSideHustleId(id: string): boolean {
  return (
    (AI_SIDE_HUSTLE_FREE_IDS as readonly string[]).includes(id) ||
    (AI_SIDE_HUSTLE_STARTER_IDS as readonly string[]).includes(id) ||
    (AI_SIDE_HUSTLE_PRO_IDS as readonly string[]).includes(id) ||
    (AI_SIDE_HUSTLE_ELITE_IDS as readonly string[]).includes(id) ||
    id.startsWith("ai-") ||
    id.includes("-ai-") ||
    id.endsWith("-ai")
  );
}

export function isAiSideHustle(h: Pick<SideHustleRecord, "id" | "name" | "category" | "description">): boolean {
  if (isAiSideHustleId(h.id)) return true;
  if (/\bAI\b/.test(h.name) || /ChatGPT/i.test(h.name)) return true;
  if (/^AI\b|AI\s*\//i.test(h.category || "")) return true;
  return false;
}

/** Free/Starter exceptions, else Elite for AI (Digital/AI policy). */
export function aiSideHustleMinTier(id: string): "free" | "starter" | "pro" | "elite" | null {
  if ((AI_SIDE_HUSTLE_FREE_IDS as readonly string[]).includes(id)) return "free";
  if ((AI_SIDE_HUSTLE_STARTER_IDS as readonly string[]).includes(id)) return "starter";
  if ((AI_SIDE_HUSTLE_ELITE_IDS as readonly string[]).includes(id)) return "elite";
  if ((AI_SIDE_HUSTLE_PRO_IDS as readonly string[]).includes(id)) return "pro";
  if (isAiSideHustleId(id)) return "elite";
  return null;
}

{
  for (const h of SIDE_HUSTLES) {
    if (!isAiSideHustle(h)) continue;
    const tier = aiSideHustleMinTier(h.id) ?? "elite";
    h.minTier = tier;
    h.freeWizardEligible = tier === "free";
  }
}

/** Spread non-Free / non-AI hustles across Starter, Pro, and Elite so Free is not the majority. */
{
  const free = new Set<string>(FREE_WIZARD_HUSTLE_IDS);
  const starter = new Set<string>(STARTER_SPREAD_HUSTLE_IDS);
  const pro = new Set<string>(PRO_SPREAD_HUSTLE_IDS);
  const elite = new Set<string>(ELITE_SPREAD_HUSTLE_IDS);
  for (const h of SIDE_HUSTLES) {
    if (isAiSideHustle(h)) continue;
    if (free.has(h.id)) {
      h.minTier = "free";
      h.freeWizardEligible = true;
      continue;
    }
    if (starter.has(h.id)) {
      h.minTier = "starter";
      h.freeWizardEligible = false;
      continue;
    }
    if (pro.has(h.id)) {
      h.minTier = "pro";
      h.freeWizardEligible = false;
      continue;
    }
    if (elite.has(h.id)) {
      h.minTier = "elite";
      h.freeWizardEligible = false;
      continue;
    }
  }
}

